        "dua_sujood" to DuaText("سوجودس منز", "جلال آسہٕ میٲنس رب یس، بلند ترین۔", "کم از کم ترٛیٚیہ لٹہ کر سجودس منٛز۔", "سادٕ کرنہٕ وز چھ نوکر پننس ربس نزدیک آسان (مسلمان 482)۔"),
        "dua_rising_ruku" to DuaText("رکو پؠٹھ چھ بڑان۔", "اللہ چھ سہ بوزن وول یس أمہ سٕنٛز تعریٖف چھ کران۔ اے أمہ سنٛد رب، ساری تعریٖف چھ توٗہنز۔", "ییٚلہ زن رکو پؠٹھ وۄپداوان چھ تہٕ سید کھڑا چھ۔", "ییٚمہ سنٛد'ربانہ و لکل ہمد'فرشتوں سۭتۍ چھ ملان، أمۍ سٕنٛدۍ پٔتمہ گناہ چھ معاف کرنہٕ یوان۔"),
        "dua_between_sajdas" to DuaText("دون سجداس درمیان", "اے میرے رب، مجھے بخش دو۔ اے میرے رب، مجھے بخش دو۔", "دونین صندودن درمیان بیٹھیان۔", "صندودن درمیان بیٹھنک سنت دعا۔"),
        "dua_before_salam_four" to DuaText("ژور چیزن پیٹھہٕ پناہ (سلامس برونٹھ)", "اے اللہ، بہٕ چھس تۄہہ جہنم کس سزا نش، قبر کس سزا نش، زندگی تہٕ موت کس آزمودن نش، تہٕ جھوٹے مسیحا (دجل) کس مقدمہٕ کس برٲئی نش پناہ طلب کران۔", "آخری تاشاہود تہٕ سلوات پتہٕ، سلامس برٛونٛہہ۔", "پیغمبر اسلام صلی اللہ علیہ وسلم ین دیت یمن ژۄن چیزن نش پناہ گزینن ہند حکم۔"),
        "dua_qunoot_witr" to DuaText("وٹرس منٛز کونوٹ", "اے اللہ، مےٚ تمن منٛز ہاو یمن ہنٛز تم ہدایت چھ دژمژ، مےٚ تم منٛز بھلائی دییو یم تم تم چھ عطا کرمژ، مےٚ تیمس منٛز نن یم تم پننس خیالس منٛز چھ تھومٕتۍ، تیمس منٛز چھ مےٚ بھلائی دیمت یس تم دیتمت، تہٕ مےٚ بچاو امہٕ برٲئی نش یس تم حکم دیتمت چھ۔ تم چھ حکم دیوان تہٕ نہٕ چھ نہٕ تم خلاف کنہہ حکم دیوان، تہٕ یس تم سۭتۍ دوستی چھ کران چھ نہٕ سہ چھ نہٕ زانٛہہ تہ ذلت یوان کرنہٕ۔ تم چھ پاک تہٕ برتر، سہٕ رب۔", "ودر دعا منٛز-پیغمبر صلی اللہ علیہ وسلم ین ہیچھنو یہ حسن ابن علی (ر) یس۔", "وترک سنت کونوت۔ (حنافیٚن منٛز چھ'اللہوما انا نسٹا انوکا'تہ مشہوٗر۔)"),
        "dua_qunoot_hanafi" to DuaText("کونوت (اللہوما انا ناسٹیناکا)", "اے اللہ، اسہ چھ تہنز مدد تہٕ تہنز معافی طلب کران، اسہ چھ تہنز اعتماد تہٕ تہنز بھروسہ کران، أس چھ بہترین طریقہٕ سۭتۍ تہنز تعریف کران، أس چھ تہنز شکر گزاری کران تہٕ چھ نہٕ شکر گزار، تہٕ أس چھ اتھ ترک کران یس تہنز نافرمانی چھ کران۔ اے اللہ، صرف چھ تہنز عبادت کران، تہنز دعا چھ کران تہٕ سماندا کران، تہنز طرف چھ أس جلدی کران تہٕ کوشش کران، تہنز رحمچ امید چھ تھوان تہٕ تہنز سزا چھ خوف کران۔ یقینی طورس پیٹھ تہنز سزا گژھن کافرن تام۔", "ودرس منٛز-ہنافین ہنٛز مشق۔", "عمر (ر) سند طرفہٕ چھ قنوتس منٛز اطلاع دنہٕ آمٕژ۔"),
        "dua_sleep_aslamtu" to DuaText("سونٛنہٕ برٛونٛہہ ٲخٕری الفاظ", "اے اللہ، بہٕ چھس پنن پان تۄہہ سپرد کران، پنن معاملہ تۄہہس تفویض کران تہٕ پننہ حفاظتس منٛز پنن کمر وقف کران، تۄہہ منٛز امید تہٕ خوفٕ سۭتۍ۔ تۄہہ نش چھ نہٕ کانٛہہ پناہ تہٕ بچنہٕ بغٲر کانٛہہ تہٕ۔ بہٕ چھس تہنٛدس کتابس پیٹھ یقین تھاوان یس تۄہہ ظٲہر کوٚر تہٕ تہنٛدس نبی یس تۄہہ سوزمت اوس۔", "ووڈو پتہٕ، دٕچھنس طرفہٕ لیٹ-سونہٕ برونٹھ چھ آخری الفاظ۔", "اگر سہ تمہ راتھ مران چھ، سہ چھ فردس (اسلام) پیٹھ مران۔"),
        "dua_waking_night" to DuaText("راتس منٛز چھ جاگنہٕ۔", "کٲنہہ تہ چھ نہٕ عبادت کرنک حق، سوائے اللہ کہ، بغٲر شریک۔ أمہ سنٛد چھ حکومت تہٕ أمہ سنٛد چھ تعریفی، تہٕ سہ چھ ہر چیزس پیٹھ طاقت۔ تمام تعریفیں چھ اللہ خٲطرٕ، جلال چھ اللہ خٲطرٕ، کٲنہہ تہ چھ نہٕ عبادت کرنک حق سوائے اللہ کہ، اللہ چھ ساروی کھوتہٕ عظیم، تہٕ اللہس علاوٕ چھنہٕ کانٛہہ طاقت تہٕ طاقت۔ اے اللہ، مےٚ بخش۔", "راتس منٛز ژھننہٕ پیٹھ۔", "أمہ سٕنٛز دعا چھ جواب دنہٕ یوان، تہٕ اگر سہ ووڈو چھ کران تہٕ دعا چھ کران، تیٚلہ چھےٚ أمہ سٕنٛز دعا قبول کرنہٕ یوان۔"),
        "dua_hamm_ibn_masud" to DuaText("دعا برائے غم (ابن مسعود)", "اے اللہ، بہٕ چھس تہنٛد نوکر، تہنٛد نوکر سنٛد نیٚچو، تہنٛد نوکر سنٛد نیٚچو۔ میٚون فورلاک چھ تہنٛدس اتھس منٛز، تہنٛد مےٚ پؠٹھ حکم چھ یوان دنہٕ، تہٕ مےٚ متعلق تہنٛد فرمان چھ انصاف۔ بہٕ چھس تۄہہ ہر تتھ ناو سۭتۍ پوچھان یس تۄہہ چھ، یتھ سۭتۍ تۄہہ پنن ناو تھوٚو، یا پنٛنس کتابس منٛز ظٲہر، یا پنٛنس کٲنٛسہ تہ مخلوق سۭتۍ ہیٚچھناو، یا نکھنہٕ چیز کس علمس منٛز پانس سۭتۍ تھونہٕ-ز تہۍ چھو قرآنس میٲنس دلک چشمہٕ، میٲنس سینچ روشنی، میٚون غم دور کرن تہٕ میٚون پریشانین ہنٛد اخراج کران۔", "غم تہٕ مصیبتس منٛز-اللہ چھ غمک جاۓ خوشی سۭتۍ نوان۔", "اللہ چھ أمہ سٕنٛز فکر تہٕ غم دور کران تہٕ أمس امہ جایہ خوشی دوان۔"),
        "dua_difficulty_sahl" to DuaText("ییلہ کنٛہہ مشکل آسہ۔", "اے اللہ، کانٛہہ تہ چھ نہٕ سہل سوائے امہ علاوٕ ز توہہ چھو سہل بناوان، تہٕ توہہ چھو یژھان مشکل آسان بناوان۔", "ییلہ کنٛہہ مشکل چھ محسوس گژھان۔", "امتحانن منٛز آسان تہٕ مشکل کامہٕ۔"),
        "dua_musibah" to DuaText("اپون اے کیلمٹی (Istirja)", "اسہ چھ اللہ ہک تہٕ اسہ گژھ واپس أمس کن۔ اے اللہ، مےٚ دو٘شو٘ منز بدلہ دو تہٕ میانہ خٲطرٕ بدلہ دو٘ووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووو", "کنہ تہ نقصان یا آفتس پیٹھ۔", "اللہ چھ یقینی طور پٲٹھۍ کینٛہہ بہتر دوان-ام سلامہ (ر) اوس پیغمبر صلی اللہ علیہ وسلم دنہٕ آمت۔"),
        "dua_debt" to DuaText("قرضہٕ پیٹھہٕ نجات خٲطرٕہ", "اے اللہ، مےٚ کریو تم چیز یم تو٘ہن غٲر قونوٗنی بناومتس خلاف جائز بناومت چھ، تہٕ تو٘ہنہٕ فضلہٕ سٕتہ بناو مےٚ تو٘سہ علاوٕ تمامن نش آزاد۔", "قرضٕ ادا کرنہٕ خٲطرٕ-علی (ر) سندٕ طرفہٕ ہیچھناونہٕ آمت۔", "اگر قرض تہ پہاڑس ہیو، خدا کریو یہٕ طے۔"),
        "dua_anger" to DuaText("ییٚلہ غصے منٛز آسہ۔", "بہٕ چھس ملحقہ شیتان نش اللہ ہس منٛز پناہ طلب کران۔", "غصے منز۔", "پیغمبر صلی اللہ علیہ وسلم ین ووٚن: اگر سہ یہ ون، تہ گژھ أمہ سنٛد غصے دور۔"),
        "dua_waswasa" to DuaText("ایمانس منٛز اوس واساسا خلاف", "بہٕ چھس اللہ تہٕ أمہ سٕنٛدۍ رسولن پؠٹھ یقین تھاوان۔", "ییلہٕ شیطانی عقیدس بارس منٛز سرگوشی چھ یوان کرنہٕ۔", "ییٚلہ یہ وٗچھان چھ، یہ ون تہٕ یتیٚتھ رک (تہٕ چھ اللہیہ نش پناہ تہ حٲصل کران)۔"),
    )
